update public.real_estate_glossary set definition='Área da projeção da edificação no terreno segundo o conceito aplicável. Na análise de terrenos e imóveis, este conceito deve ser cruzado com o instrumento territorial, regulamento, cartografia, condicionantes e procedimento aplicáveis ao caso concreto. Uma referência isolada raramente é suficiente para concluir sobre edificabilidade, licenciamento ou valor do ativo.', updated_at=now() where term='Área de Implantação';
