update public.real_estate_glossary set definition='Limitação ou encargo que pode afetar um prédio, de natureza privada ou administrativa. Este conceito pode afetar a titularidade, utilização, transmissão ou disponibilidade do imóvel e, por isso, deve ser confirmado através da documentação adequada. O consultor deve reconhecer o seu impacto comercial sem substituir a interpretação jurídica do caso concreto.', updated_at=now() where term='Servidão';
