update public.real_estate_glossary set definition='Estratégia de comprar, valorizar e revender num horizonte relativamente curto. É uma ferramenta de análise e comparação, não uma garantia de retorno. Para ser útil, devem ser explicitadas a fórmula, o período, os custos incluídos, as receitas consideradas e as premissas usadas, permitindo comparar cenários de forma consistente.', updated_at=now() where term='Flip';
update public.real_estate_glossary set definition='Aquisição de imóvel com objetivo principal de arrendamento. É uma ferramenta de análise e comparação, não uma garantia de retorno. Para ser útil, devem ser explicitadas a fórmula, o período, os custos incluídos, as receitas consideradas e as premissas usadas, permitindo comparar cenários de forma consistente.', updated_at=now() where term='Buy-to-let';
update public.real_estate_glossary set definition='Expressão para imóvel/projeto entregue pronto a utilizar segundo o âmbito contratado. É sobretudo uma designação comercial e deve ser usada de forma coerente com as características reais do imóvel. A comunicação não deve criar a impressão de que uma característica estética ou comercial corresponde, por si só, a uma categoria jurídica, urbanística ou técnica.', updated_at=now() where term='Turnkey';
update public.real_estate_glossary set definition='Designação comercial de unidade de topo com características diferenciadas. É sobretudo uma designação comercial e deve ser usada de forma coerente com as características reais do imóvel. A comunicação não deve criar a impressão de que uma característica estética ou comercial corresponde, por si só, a uma categoria jurídica, urbanística ou técnica.', updated_at=now() where term='Penthouse';
