update public.real_estate_glossary set definition='Forma corrente de indicar o número de quartos: T0, T1, T2 e seguintes. É sobretudo uma designação comercial e deve ser usada de forma coerente com as características reais do imóvel. A comunicação não deve criar a impressão de que uma característica estética ou comercial corresponde, por si só, a uma categoria jurídica, urbanística ou técnica.', updated_at=now() where term='T0/T1/T2';
update public.real_estate_glossary set definition='Termo inglês para determinação de valor segundo método/finalidade. É uma ferramenta de análise e comparação, não uma garantia de retorno. Para ser útil, devem ser explicitadas a fórmula, o período, os custos incluídos, as receitas consideradas e as premissas usadas, permitindo comparar cenários de forma consistente.', updated_at=now() where term='Valuation';
update public.real_estate_glossary set definition='Análise comercial baseada em imóveis comparáveis para apoiar posicionamento/preço. No trabalho comercial, o termo ajuda a organizar a relação com proprietários, compradores e oportunidades ao longo do processo. Deve ser usado com critérios internos claros para que toda a equipa saiba exatamente em que fase está o contacto e qual é o próximo passo.', updated_at=now() where term='CMA';
